def verify_token(token, key):
    '''
מאמת טוקן JWT.

    הפונקציה מפענחת את הטוקן ומאמתת את החתימה מול רשימה של 
    אלגוריתמים נתמכים, כולל HS256 ו-'none'.
    '''
    try:
        # פענוח ואימות הטוקן
        # שימו לב: שימוש באלגוריתם 'none' הוא מסוכן ביותר וצריך להימנע ממנו
        # אלא אם כן אתם מבינים היטב את ההשלכות הביטחוניות.
        # הוא כלול כאן לבקשת המשתמש.
        decoded_payload = jwt.decode(token, key, algorithms=['HS256', 'none'])
        return decoded_payload
    except jwt.ExpiredSignatureError:
        # הטוקן פג תוקף
        return {"error": "Token has expired"}
    except jwt.InvalidTokenError:
        # הטוקן אינו תקף (למשל, חתימה שגויה, מבנה שגוי)
        return {"error": "Invalid token"}
    except Exception as e:
        # טיפול בשגיאות אחרות
        return {"error": f"An unexpected error occurred: {e}"}

